/**
 * Enum representing the available types of content configurations for the filter factory system.
 * - `List`: Hierarchical item selection.
 * - `Datepicker`: Calendar-based date selection.
 * - `String`: Text input for user-entered values.
 */
export enum ContentTypes {
  List = 'list',
  Datepicker = 'datepicker',
  String = 'string',
}
